settings.custom_css:
/* Pages using both Elementor AND Divi */
body.elementor-page.et_pb_button_helper_class #sidebar {
  display: none;
}

body.elementor-page.et_pb_button_helper_class #left-area {
  width: 100% !important;
  float: none !important;
  padding-right: 0 !important;
  padding-bottom: 0 !important;
}

body.elementor-page.et_pb_button_helper_class #main-content .container {
  width: 100%;
  max-width: 100%;
  padding-top: 0;
}

body.elementor-page.et_pb_button_helper_class #main-content .container:before {
  display: none;
}
